DROP POLICY "Staff can view own profile and admins view staff" ON public.profiles;
CREATE POLICY "Staff can view own profile and admins view assigned staff" ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR (public.is_staff_admin(auth.uid()) AND (EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.role='super_admin') OR EXISTS (SELECT 1 FROM public.staff_branch_assignments a WHERE a.user_id=profiles.id AND a.branch_name=(SELECT branch FROM public.profiles WHERE id=auth.uid())))));
DROP POLICY "Staff see own role and admins see staff roles" ON public.user_roles;
CREATE POLICY "Staff see own role and admins see assigned roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR (public.is_staff_admin(auth.uid()) AND (EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.role='super_admin') OR EXISTS (SELECT 1 FROM public.staff_branch_assignments a WHERE a.user_id=user_roles.user_id AND a.branch_name=(SELECT branch FROM public.profiles WHERE id=auth.uid())))));